{
  "status": "plan",
  "steps": [
    {
      "op": "derive",
      "input": "employees",
      "as": "result",
      "column": "band",
      "expr": "'senior' if salary >= 140000 else 'mid' if salary >= 100000 else 'junior'"
    }
  ]
}

{
  "status": "plan",
  "steps": [
    {
      "op": "filter",
      "input": "students",
      "as": "passed",
      "where": "not is_null(math) and not is_null(science) and not is_null(english) and math >= 50 and science >= 50 and english >= 50"
    },
    {
      "op": "sort",
      "input": "passed",
      "as": "ordered",
      "by": [
        {
          "column": "attendance_pct",
          "order": "desc"
        }
      ]
    },
    {
      "op": "select",
      "input": "ordered",
      "as": "result",
      "columns": [
        "name",
        "section",
        "attendance_pct"
      ]
    }
  ]
}

{
  "status": "plan",
  "steps": [
    {
      "op": "aggregate",
      "input": "expenses",
      "as": "person_totals",
      "group_by": [
        "paid_by"
      ],
      "metrics": [
        {
          "as": "person_amount",
          "fn": "sum",
          "column": "amount_inr"
        }
      ]
    },
    {
      "op": "derive",
      "input": "person_totals",
      "as": "person_keyed",
      "column": "join_key",
      "expr": "1"
    },
    {
      "op": "aggregate",
      "input": "expenses",
      "as": "total",
      "group_by": [],
      "metrics": [
        {
          "as": "total_amount",
          "fn": "sum",
          "column": "amount_inr"
        }
      ]
    },
    {
      "op": "derive",
      "input": "total",
      "as": "total_keyed",
      "column": "join_key",
      "expr": "1"
    },
    {
      "op": "join",
      "input": "person_keyed",
      "right": "total_keyed",
      "as": "joined",
      "on": [
        "join_key"
      ],
      "how": "inner"
    },
    {
      "op": "derive",
      "input": "joined",
      "as": "with_share",
      "column": "share_pct",
      "expr": "round((person_amount * 100 / total_amount) if (not is_null(total_amount) and total_amount != 0) else 0, 1)"
    },
    {
      "op": "select",
      "input": "with_share",
      "columns": [
        "paid_by",
        "share_pct"
      ]
    }
  ]
}

{
  "status": "plan",
  "steps": [
    {
      "op": "filter",
      "input": "students",
      "as": "students_with_marks",
      "where": "not is_null(math) and not is_null(science) and not is_null(english)"
    },
    {
      "op": "derive",
      "input": "students_with_marks",
      "as": "students_total",
      "column": "total",
      "expr": "math + science + english"
    },
    {
      "op": "select",
      "input": "students_total",
      "as": "students_final",
      "columns": [
        "name",
        "total"
      ]
    },
    {
      "op": "sort",
      "input": "students_final",
      "as": "result",
      "by": [
        {
          "column": "total",
          "order": "desc"
        },
        {
          "column": "name",
          "order": "asc"
        }
      ]
    }
  ]
}

{
  "status": "plan",
  "steps": [
    {
      "op": "aggregate",
      "input": "trips",
      "as": "city_totals",
      "group_by": [
        "city"
      ],
      "metrics": [
        {
          "as": "distance_sum",
          "fn": "sum",
          "column": "distance_km"
        },
        {
          "as": "duration_min_sum",
          "fn": "sum",
          "column": "duration_min"
        }
      ]
    },
    {
      "op": "derive",
      "input": "city_totals",
      "as": "city_speed",
      "column": "speed_kmh",
      "expr": "round(distance_sum / (duration_min_sum / 60), 1) if not is_null(duration_min_sum) and duration_min_sum > 0 else null"
    },
    {
      "op": "select",
      "input": "city_speed",
      "as": "result",
      "columns": [
        "city",
        "speed_kmh"
      ]
    }
  ]
}

{
  "status": "plan",
  "steps": [
    {
      "op": "aggregate",
      "input": "trips",
      "as": "driver_totals",
      "group_by": [
        "driver"
      ],
      "metrics": [
        {
          "as": "total_distance_km",
          "fn": "sum",
          "column": "distance_km"
        },
        {
          "as": "total_duration_min",
          "fn": "sum",
          "column": "duration_min"
        }
      ]
    },
    {
      "op": "derive",
      "input": "driver_totals",
      "as": "driver_speeds",
      "column": "speed_kmh",
      "expr": "not is_null(total_duration_min) and total_duration_min > 0 and not is_null(total_distance_km) ? round(total_distance_km / (total_duration_min / 60), 1) : null"
    },
    {
      "op": "select",
      "input": "driver_speeds",
      "as": "driver_speeds_selected",
      "columns": [
        "driver",
        "speed_kmh"
      ]
    },
    {
      "op": "sort",
      "input": "driver_speeds_selected",
      "as": "driver_speeds_sorted",
      "by": [
        {
          "column": "speed_kmh",
          "order": "asc"
        }
      ]
    }
  ]
}

