{
  "status": "plan",
  "steps": [
    {
      "op": "derive",
      "input": "requests",
      "as": "requests_success",
      "column": "is_success",
      "expr": "1 if (status >= 200 and status < 300) else 0"
    },
    {
      "op": "aggregate",
      "input": "requests_success",
      "as": "per_endpoint",
      "group_by": [
        "endpoint"
      ],
      "metrics": [
        {
          "as": "total_requests",
          "fn": "count"
        },
        {
          "as": "success_requests",
          "fn": "sum",
          "column": "is_success"
        }
      ]
    },
    {
      "op": "derive",
      "input": "per_endpoint",
      "as": "success_rate",
      "column": "success_pct",
      "expr": "round(100 * success_requests / total_requests, 1) if total_requests > 0 else 0"
    },
    {
      "op": "select",
      "input": "success_rate",
      "as": "output",
      "columns": [
        "endpoint",
        "success_pct"
      ]
    }
  ]
}

