{
  "status": "plan",
  "steps": [
    {
      "op": "filter",
      "input": "subscriptions",
      "as": "active_subs",
      "where": "is_null(cancelled_on)"
    },
    {
      "op": "aggregate",
      "input": "active_subs",
      "as": "active_agg",
      "group_by": [
        "plan"
      ],
      "metrics": [
        {
          "as": "total_seats",
          "fn": "sum",
          "column": "seats"
        },
        {
          "as": "active_sub_count",
          "fn": "count",
          "column": "sub_id"
        }
      ]
    },
    {
      "op": "rename",
      "input": "active_agg",
      "as": "active_agg_named",
      "columns": {
        "plan": "active_plan"
      }
    },
    {
      "op": "join",
      "input": "plans",
      "as": "plans_active",
      "right": "active_agg_named",
      "left_on": [
        "plan"
      ],
      "right_on": [
        "active_plan"
      ],
      "how": "left"
    },
    {
      "op": "derive",
      "input": "plans_active",
      "as": "plans_util",
      "column": "utilisation",
      "expr": "round(total_seats / (seat_limit * active_sub_count), 2) if not is_null(active_sub_count) and active_sub_count > 0 else null"
    },
    {
      "op": "select",
      "input": "plans_util",
      "as": "final",
      "columns": [
        "plan",
        "utilisation"
      ]
    }
  ]
}

